{
  "id": "activate_update",
  "name": "Activate a staged update",
  "description": "Verify a staged update once more and record the swap for the next start. The folders are exchanged by a separate process before the application loads, so the running code is never replaced underneath itself, the previous app folder is kept as a backup, and data/ is not touched.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "staged": {
        "type": "string",
        "description": "Staged folder; the most recent one when left empty.",
        "x-cy-kind": "Directory",
        "default": ""
      }
    },
    "required": [],
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "pending": {
        "type": "string",
        "description": "The recorded request.",
        "x-cy-kind": "File",
        "maxLength": 1024
      },
      "restartRequired": {
        "type": "boolean"
      },
      "mode": {
        "type": "string"
      },
      "version": {
        "type": "string"
      },
      "fromVersion": {
        "type": "string"
      },
      "source": {
        "type": "string"
      },
      "requestedAt": {
        "type": "string"
      },
      "verified": {
        "type": "object",
        "additionalProperties": true
      }
    },
    "required": [
      "pending",
      "restartRequired"
    ],
    "additionalProperties": false
  },
  "resourceRequirements": {
    "ramBytes": 268435456
  },
  "supportedBackends": [],
  "permissions": [],
  "canRunAsync": true,
  "canCancel": true,
  "supportsProgress": true,
  "x-cy-category": "Maintenance",
  "x-cy-tags": []
}
python app/tool.py describe-operation activate_update

{
  "id": "analyze_views",
  "name": "Analyse a set of pictures",
  "description": "Pre-flight for a reconstruction: segmentation, view poses, same-object check, coverage map and the list of viewpoints that are missing.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "images": {
        "type": "array",
        "minItems": 1,
        "maxItems": 12,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image"
          ],
          "properties": {
            "image": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Picture of the object (PNG, JPEG, WebP, BMP, TIFF; 64 MiB max). An absolute path on the Tool host is accepted and imported automatically into the private job workspace; an alpha channel is used as the object mask."
            },
            "label": {
              "type": "string",
              "enum": [
                "Front",
                "FrontRight",
                "Right",
                "RearRight",
                "Back",
                "RearLeft",
                "Left",
                "FrontLeft",
                "Top",
                "Bottom"
              ],
              "description": "Optional human view label. Internally converted to continuous angles. For Top/Bottom the in-plane orientation is searched automatically unless azimuth is given."
            },
            "azimuth": {
              "type": "number",
              "minimum": -360,
              "maximum": 360,
              "description": "Degrees around the vertical axis: 0 = camera in front of the object, 90 = camera on the object's right side, 180 = behind. Overrides label."
            },
            "elevation": {
              "type": "number",
              "minimum": -90,
              "maximum": 90,
              "description": "Degrees above (+) or below (-) the horizontal plane."
            },
            "roll": {
              "type": "number",
              "minimum": -180,
              "maximum": 180,
              "description": "Camera roll in degrees, 0 when the horizon is level."
            },
            "fov": {
              "type": "number",
              "minimum": 0,
              "maximum": 120,
              "description": "Field of view of the FULL picture along its longest side, in degrees. 0 = orthographic drawing. Default 35."
            },
            "weight": {
              "type": "number",
              "minimum": 0.05,
              "maximum": 1,
              "description": "Confidence weight of this real view (default 1.0)."
            },
            "mask": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Optional object mask (white = object). Replaces automatic segmentation for this picture."
            },
            "box": {
              "type": "array",
              "items": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "minItems": 4,
              "maxItems": 4,
              "description": "Optional SAM prompt box [x0, y0, x1, y1] normalised to the picture, when the object is not the salient central subject."
            }
          }
        },
        "description": "One to twelve real pictures of the SAME object. Real pictures always win over synthetic data."
      },
      "generated_views": {
        "type": "array",
        "maxItems": 12,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image",
            "relative_azimuth",
            "elevation"
          ],
          "properties": {
            "image": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Synthetic view produced by a novel-view model (Zero123++, SyncDreamer, Wonder3D...). Never trusted like a photograph."
            },
            "source": {
              "type": "integer",
              "minimum": 0,
              "default": 0,
              "description": "Index in `images` of the real picture the view was generated from."
            },
            "relative_azimuth": {
              "type": "number",
              "minimum": -360,
              "maximum": 360,
              "description": "Requested azimuth relative to the source picture, degrees."
            },
            "elevation": {
              "type": "number",
              "minimum": -90,
              "maximum": 90,
              "description": "Requested absolute elevation, degrees."
            },
            "fov": {
              "type": "number",
              "minimum": 0,
              "maximum": 120,
              "default": 30,
              "description": "Field of view of the generator camera (Zero123++ v1.2: 30)."
            },
            "weight": {
              "type": "number",
              "minimum": 0.05,
              "maximum": 0.9,
              "description": "Weight of this synthetic view (default generated_view_weight)."
            },
            "mask": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Optional mask of the synthetic view."
            }
          }
        },
        "default": [],
        "description": "Optional synthetic views with their requested poses. They only vote with a reduced weight and can never carve away what a real picture shows."
      },
      "segmentation_model": {
        "type": "string",
        "enum": [
          "auto",
          "none",
          "sam2.1-hiera-tiny",
          "sam2.1-hiera-small",
          "sam2.1-hiera-base-plus",
          "sam2.1-hiera-large"
        ],
        "default": "auto",
        "description": "SAM 2.1 checkpoint for the object mask. auto = preferred installed model, else classical segmentation (alpha / plain background / GrabCut). none = classical only."
      },
      "depth_model": {
        "type": "string",
        "enum": [
          "auto",
          "none",
          "depth-anything-v2-small",
          "depth-anything-v2-base",
          "depth-anything-v2-large"
        ],
        "default": "auto",
        "description": "Depth Anything V2 checkpoint (relative depth, low-confidence cue). Base and Large are CC-BY-NC-4.0 and require a personal licence acceptance."
      },
      "camera_model": {
        "type": "string",
        "enum": [
          "auto",
          "none",
          "perspective-fields-paramnet-360cities"
        ],
        "default": "auto",
        "description": "Perspective Fields (Paramnet-360Cities-edina-centered): roll, pitch (elevation = -pitch) and field of view of each real picture. Applied only to values the user did not give and only when the picture shows a scene; on a cut-out object the cue is reported but not used. Adobe Research License, non-commercial: personal acceptance required."
      },
      "device": {
        "type": "string",
        "enum": [
          "auto",
          "cuda",
          "cpu"
        ],
        "default": "auto",
        "description": "Device of the AI understanding stage. auto = CUDA when PyTorch sees it, else CPU. The fitting engine always runs on the CPU."
      },
      "view_synthesis": {
        "type": "string",
        "enum": [
          "off",
          "auto",
          "always"
        ],
        "default": "auto",
        "description": "Missing-view generation with Zero123++ v1.2 (six views at known poses from one real picture, CUDA only). auto = only when the Real Coverage Score is below synthesis_coverage_threshold and the model is installed; always = generate or fail; off = never. Generated views vote with generated_view_weight and never override a real picture."
      },
      "view_synthesis_model": {
        "type": "string",
        "enum": [
          "auto",
          "zero123plus-v1.2",
          "wonder3d-v1.0",
          "syncdreamer"
        ],
        "default": "auto",
        "description": "Missing-view generator. auto = first installed of Zero123++ v1.2 (6 views, absolute elevations +20/-10, FOV 30), Wonder3D v1.0 (6 orthographic views in the frame of the input picture, colour + normals) and SyncDreamer (16 views at a fixed elevation of 30 degrees). Wonder3D and SyncDreamer run in their own environment and pinned source checkout (Installation tab). All need a CUDA GPU."
      },
      "synthesis_source": {
        "type": "integer",
        "minimum": -1,
        "maximum": 11,
        "default": -1,
        "description": "Index in `images` of the picture given to Zero123++. -1 = first picture that is not a top/bottom view."
      },
      "synthesis_steps": {
        "type": "integer",
        "minimum": 5,
        "maximum": 200,
        "description": "Diffusion steps of the generator. Omitted = its own default (Zero123++ 36, Wonder3D 50, SyncDreamer 50)."
      },
      "synthesis_seed": {
        "type": "integer",
        "minimum": 0,
        "maximum": 2147483647,
        "default": 0,
        "description": "Zero123++ random seed. The same seed, weights and runtime give the same views; bit-exact reproduction across GPUs is not promised."
      },
      "synthesis_guidance": {
        "type": "number",
        "minimum": 1,
        "maximum": 10,
        "description": "Classifier-free guidance scale. Omitted = the generator default (Zero123++ 4.0, Wonder3D 3.0, SyncDreamer 2.0)."
      },
      "synthesis_coverage_threshold": {
        "type": "number",
        "minimum": 0,
        "maximum": 1,
        "default": 0.6,
        "description": "view_synthesis = auto generates views when the Real Coverage Score is below this value."
      },
      "symmetry": {
        "type": "string",
        "enum": [
          "Off",
          "Auto",
          "Force X",
          "Force Y",
          "Force Z"
        ],
        "default": "Auto",
        "description": "Mirror plane normal. Auto measures bilateral symmetry (normal = Z, left/right) from several views, or assumes it for a single picture. Force X = front/back, Force Y = top/bottom, Force Z = left/right."
      },
      "use_depth": {
        "type": "boolean",
        "default": true,
        "description": "Use the depth maps for pose estimation and concavity carving."
      },
      "register_views": {
        "type": "boolean",
        "default": true,
        "description": "Classical registration of real views (OpenCV SIFT + essential matrix) for pictures without a pose."
      },
      "refine_poses": {
        "type": "boolean",
        "default": true,
        "description": "Refine unposed views by silhouette coherence."
      },
      "default_azimuth": {
        "type": "number",
        "minimum": -360,
        "maximum": 360,
        "default": 35,
        "description": "Azimuth assumed when nothing else is known (degrees)."
      },
      "default_elevation": {
        "type": "number",
        "minimum": -90,
        "maximum": 90,
        "default": 12,
        "description": "Elevation assumed when nothing else is known (degrees)."
      },
      "default_fov": {
        "type": "number",
        "minimum": 0,
        "maximum": 120,
        "default": 35,
        "description": "Field of view assumed for pictures without one (degrees, 0 = orthographic)."
      },
      "real_view_weight": {
        "type": "number",
        "minimum": 0.1,
        "maximum": 1,
        "default": 1.0,
        "description": "Weight of real pictures."
      },
      "generated_view_weight": {
        "type": "number",
        "minimum": 0.05,
        "maximum": 0.9,
        "default": 0.45,
        "description": "Weight of synthetic views (recommended 0.3 to 0.6)."
      },
      "mirrored_view_weight": {
        "type": "number",
        "minimum": 0.05,
        "maximum": 1,
        "default": 0.8,
        "description": "Weight of mirrored real views, multiplied by the symmetry confidence."
      },
      "single_view_symmetry_confidence": {
        "type": "number",
        "minimum": 0,
        "maximum": 1,
        "default": 0.5,
        "description": "Confidence of the assumed symmetry when it cannot be measured."
      },
      "symmetry_threshold": {
        "type": "number",
        "minimum": 0.5,
        "maximum": 1,
        "default": 0.93,
        "description": "Auto symmetry: minimal ratio of silhouette coherence with/without mirrored views."
      },
      "depth_margin": {
        "type": "number",
        "minimum": 0.02,
        "maximum": 0.5,
        "default": 0.12,
        "description": "Depth carving safety margin, fraction of the object size."
      },
      "complexity": {
        "type": "string",
        "enum": [
          "UltraSimple",
          "Simple",
          "Medium"
        ],
        "default": "Simple",
        "description": "Budget preset. UltraSimple: 2-4 sections, about 20-100 triangles. Simple: 4-8 sections, 100-500. Medium: 8-16 sections, 500-2000. Targets, not hard limits."
      }
    },
    "required": [
      "images"
    ],
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "report_file": {
        "type": "string",
        "x-cy-kind": "File",
        "description": "JSON report: views, poses, coverage, scores, primitives, optimisation trace, texture sources.",
        "contentMediaType": "application/json"
      },
      "preview_file": {
        "type": "string",
        "x-cy-kind": "File",
        "description": "PNG contact sheet: mask (green), support volume (yellow), proxy outline (red) for every view.",
        "contentMediaType": "image/png"
      },
      "real_view_count": {
        "type": "integer"
      },
      "generated_view_count": {
        "type": "integer"
      },
      "real_coverage_score": {
        "type": "number",
        "description": "Real Coverage Score, 0..1 over the view sphere."
      },
      "expected_reconstruction_confidence": {
        "type": "number",
        "description": "0..1; capped at 0.5 for a single picture."
      },
      "symmetry_axis": {
        "type": "string"
      },
      "is_hypothesis": {
        "type": "boolean",
        "description": "True when only one real picture was available."
      },
      "missing_views": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "understanding": {
        "type": "object",
        "description": "Models and device actually used, measured peak VRAM."
      }
    },
    "required": [
      "report_file",
      "preview_file",
      "real_coverage_score",
      "expected_reconstruction_confidence"
    ],
    "additionalProperties": false
  },
  "resourceRequirements": {
    "ramBytes": 8589934592,
    "vramBytes": {
      "auto": 4294967296
    }
  },
  "supportedBackends": [
    "proxyfit"
  ],
  "permissions": [],
  "canRunAsync": true,
  "canCancel": true,
  "supportsProgress": true,
  "x-cy-category": "Views",
  "x-cy-tags": [
    "ported"
  ],
  "x-cy-origin": {
    "tool": "CyTools_MeshConstruct",
    "operation": "analyze_views",
    "note": "Schemas reused verbatim from the absorbed Tool."
  }
}
python app/tool.py describe-operation analyze_views

{
