{
  "id": "complete_subject",
  "name": "Complete the subject with generated views (Wonder3D)",
  "description": "From one picture, generate the right, left and back views with Wonder3D around the vertical axis of the picture, then cut the four views out at one common scale: a subject set for the four-view path of LocalMesh. Only for a level front view: with a three-quarter or top view the generated views are tilted and the fusion deforms the object. The generated views are marked as such, and LocalMesh measures their angles itself.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "image": {
        "type": "string",
        "description": "Reference picture of the subject (the front).",
        "x-cy-kind": "Image",
        "maxLength": 1024
      },
      "subject_set": {
        "type": "string",
        "description": "Folder produced by prepare_subject; its front cut-out is used.",
        "x-cy-kind": "Directory",
        "default": ""
      },
      "seed": {
        "type": "integer",
        "description": "Wonder3D random seed.",
        "default": 42,
        "x-cy-kind": "Integer",
        "minimum": 0,
        "maximum": 2147483647
      },
      "steps": {
        "type": "integer",
        "description": "Diffusion steps of Wonder3D.",
        "default": 50,
        "x-cy-kind": "Integer",
        "minimum": 10,
        "maximum": 100,
        "x-cy-ui": {
          "advanced": true
        }
      },
      "guidance": {
        "type": "number",
        "description": "Guidance scale of Wonder3D.",
        "default": 3.0,
        "x-cy-kind": "Float",
        "minimum": 1.0,
        "maximum": 10.0,
        "x-cy-ui": {
          "advanced": true
        }
      },
      "gpu": {
        "type": "integer",
        "description": "GPU index.",
        "default": 0,
        "x-cy-kind": "Integer",
        "minimum": 0,
        "maximum": 7,
        "x-cy-ui": {
          "advanced": true
        }
      }
    },
    "required": [],
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "subject_set": {
        "type": "string",
        "description": "The four cut-outs and subject.json.",
        "x-cy-kind": "Directory",
        "maxLength": 1024
      },
      "subject_file": {
        "type": "string",
        "description": "subject.json.",
        "x-cy-kind": "File",
        "maxLength": 1024
      },
      "contact_sheet": {
        "type": "string",
        "description": "The four views side by side.",
        "x-cy-kind": "Image",
        "maxLength": 1024
      },
      "views": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": true
        }
      },
      "viewCount": {
        "type": "integer"
      },
      "generated": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "generator": {
        "type": "string"
      },
      "wonder3d_folder": {
        "type": "string",
        "description": "The six raw Wonder3D views and their normal maps.",
        "x-cy-kind": "Directory",
        "maxLength": 1024
      },
      "notes": {
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    },
    "required": [
      "subject_set",
      "subject_file",
      "views"
    ],
    "additionalProperties": false
  },
  "resourceRequirements": {
    "ramBytes": 12884901888,
    "vramBytes": {
      "auto": 10737418240
    },
    "diskBytes": 1073741824
  },
  "supportedBackends": [
    "wonder3d"
  ],
  "permissions": [],
  "canRunAsync": true,
  "canCancel": true,
  "supportsProgress": true,
  "x-cy-category": "Views",
  "x-cy-tags": []
}
python app/tool.py describe-operation complete_subject

{
  "id": "construct_proxy",
  "name": "Construct a proxy mesh from pictures",
  "description": "Build a simple, clean, mostly hard-surface proxy mesh (lofted cross-sections, extruded polygons, boxes, cylinders) from one or several pictures of the same object, and project the pictures on it. AI models only supply masks, relative depth, camera poses and optional synthetic views.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "images": {
        "type": "array",
        "minItems": 1,
        "maxItems": 12,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image"
          ],
          "properties": {
            "image": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Picture of the object (PNG, JPEG, WebP, BMP, TIFF; 64 MiB max). An absolute path on the Tool host is accepted and imported automatically into the private job workspace; an alpha channel is used as the object mask."
            },
            "label": {
              "type": "string",
              "enum": [
                "Front",
                "FrontRight",
                "Right",
                "RearRight",
                "Back",
                "RearLeft",
                "Left",
                "FrontLeft",
                "Top",
                "Bottom"
              ],
              "description": "Optional human view label. Internally converted to continuous angles. For Top/Bottom the in-plane orientation is searched automatically unless azimuth is given."
            },
            "azimuth": {
              "type": "number",
              "minimum": -360,
              "maximum": 360,
              "description": "Degrees around the vertical axis: 0 = camera in front of the object, 90 = camera on the object's right side, 180 = behind. Overrides label."
            },
            "elevation": {
              "type": "number",
              "minimum": -90,
              "maximum": 90,
              "description": "Degrees above (+) or below (-) the horizontal plane."
            },
            "roll": {
              "type": "number",
              "minimum": -180,
              "maximum": 180,
              "description": "Camera roll in degrees, 0 when the horizon is level."
            },
            "fov": {
              "type": "number",
              "minimum": 0,
              "maximum": 120,
              "description": "Field of view of the FULL picture along its longest side, in degrees. 0 = orthographic drawing. Default 35."
            },
            "weight": {
              "type": "number",
              "minimum": 0.05,
              "maximum": 1,
              "description": "Confidence weight of this real view (default 1.0)."
            },
            "mask": {
              "type": "string",
              "x-cy-kind": "File",
              "description": "Optional object mask (white = object). Replaces automatic segmentation for this picture."
            },
            "box": {
              "type": "array",
              "items": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "minItems": 4,
              "maxItems": 4,
              "description": "Optional SAM prompt box [x0, y0, x1, y1] normalised to the picture, when the object is not the salient central subject."
            }
          }
        },
        "description": "One to twelve real pictures of the SAME object. Real pictures always win over synthetic data."
      },
      "generated_views": {
        "type": "array",
        "maxItems": 12,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image",
            "relative_azimuth",
            "elevation"
          ],
          "properties": {
            "image": {
